/* SPIEG_EN — versione inglese delle note metodologiche dei grafici (05b-spiegazioni.js):
   stesse chiavi e stessa struttura di SPIEG. Una voce che manca ricade sull'italiano. */
const SPIEG_EN={
'distribuzione':{t:'Distribution of work across muscle groups',
  dove:'Weights (side panel) · ⚖ Balance · Progress · Report',
  a:`The radar chart describes the <b>shape</b> of the weekly weight-training load: what share of the sets goes to each of the six groups (Legs, Chest, Back, Shoulders, Arms, Core). It is a measure of <b>proportion</b>, independent of total volume. The green band is the typical shape of a reference chosen by experience and training type; the caption states how many programs or studies it rests on.`,
  s:[['What it shows',`Each axis is the percentage share of one group in the total weight-training sets. In <b>Weights</b> and in <b>⚖ Balance</b> the program being written is used; in <b>Progress</b> and in the <b>Report</b>, the last week saved in History. Cardio is excluded: it would change the share of every other group.`],
   ['Input data',`For each row: exercise and number of sets. From the catalog: the exercise’s primary and secondary muscles, mapped to the six groups (17 muscles → 6 groups). Alternatively, if selected in ⚙ Reference, the external muscle map (smyrdev, 1.0 direct / 0.5 indirect per movement pattern).`],
   ['Method and formulas',`A set is <b>direct</b> for the group of a primary muscle and <b>indirect</b> for the group of a muscle that is only secondary (a group with a primary muscle stays direct). With weights <i>w</i><sub>d</sub> = 1.0 and <i>w</i><sub>i</sub> = 0.5 (defaults, provisional):
     <div class="spf">S<sub>g</sub> = <i>w</i><sub>d</sub> · D<sub>g</sub> + <i>w</i><sub>i</sub> · I<sub>g</sub><span class="spn">(1)</span></div>
     <div class="spf">q<sub>g</sub> = <span class="fr"><i>S<sub>g</sub></i><i>Σ<sub>k</sub> S<sub>k</sub></i></span> × 100<span class="spn">(2)</span></div>
     where D<sub>g</sub> and I<sub>g</sub> are the direct and indirect sets of group <i>g</i>. The reference is computed with the <b>same</b> count on the chosen entries (published programs or study protocols): for each group the band runs from the 10th to the 90th percentile of the shares (linear interpolation), rounded outward. The label turns red below ¾ of the 10th percentile or above 5/4 of the 90th. With fewer than 5 entries the band is not drawn; from 5 to 9 it is dashed.`],
   ['Worked example',`Program: 4 sets of squat and 3 of flat bench press. Squat: quadriceps primary (Legs direct); lower back, glutes, hamstrings, calves secondary (Back indirect). Bench press: pectorals primary; shoulders and triceps secondary.
     <div class="spf">Legs 4 · Chest 3 · Back 4×0.5 = 2 · Shoulders 3×0.5 = 1.5 · Arms 1.5 · Core 0 &nbsp;→&nbsp; total 12</div>
     Shares: Legs 33%, Chest 25%, Back 17%, Shoulders 12.5%, Arms 12.5%, Core 0%. With the default reference (Chest 6–13%, red above 16%) Chest turns red: the week is unbalanced toward horizontal pushing.`],
   ['How to read it',`Shape matters, not size: a light week and a heavy week distributed in the same way give the same drawing. The orange polygon should stay inside the green ring, which is not regular because the groups gather a different number of muscles and of indirect work. For quantity, use the “Sets per group” list.`],
   ['Limitations',`The 1.0 / 0.5 weights are a convention (fractional sets), not a measure of muscle activation. The references describe published programs or study protocols, not the optimum for an individual: the level of the programs is declared by the author, the experience in the studies is that of the participants. Three groups (Legs, Back, Arms) sum different muscles: a 30% share of Legs may be all quadriceps. With “Fable programs” on, where real programs are missing the purple band comes from programs generated by the Fable model: a hypothesis, not data.`]],
  b:['Schoenfeld BJ, Grgic J, Haun C, Itagaki T, Helms ER (2019). Calculating set-volume for the limb muscles with the performance of multi-joint exercises. <i>Sports</i> 7(7):177.',
     'Pelland JC et al. (2025). The resistance training dose response: meta-regressions exploring the effects of weekly volume and frequency on hypertrophy and strength. <i>Sports Medicine</i>, doi:10.1007/s40279-025-02344-w.',
     'Hyndman RJ, Fan Y (1996). Sample quantiles in statistical packages. <i>The American Statistician</i> 50(4):361–365.',
     'TMS references: StrengthLog, Muscle &amp; Strength, depot.fitness (CC BY 4.0), Liftosaur and other public programs from 30 websites; protocol corpus v0.7 and open-access articles. Full list in ⚙ Reference.']},

'serie-gruppo':{t:'Sets per muscle group and useful zone',
  dove:'Weights (side panel) · ⚖ Balance · History · Progress',
  a:`The list (and, in Progress, the bar chart) gives the <b>quantity</b> of weekly work for each group, in sets, separating the direct part from the indirect one, and compares it with a useful zone derived from balanced published programs.`,
  s:[['What it shows',`For each group, the sets of the week: in <b>Weights</b> and in <b>⚖ Balance</b> those of the program being written, in <b>History</b> the weekly average of the filtered rows, in <b>Progress</b> the last saved week, with Cardio in addition. The bar is solid for the direct part and light for the indirect one; the green ticks mark the group’s useful zone.`],
   ['Input data',`Exercise and sets of each row; primary and secondary muscles from the catalog; for Cardio, the minutes of the activities (Cardio tab) and of warm-up cardio.`],
   ['Method and formulas',`Same count as the radar chart:
     <div class="spf">S<sub>g</sub> = <i>w</i><sub>d</sub> · D<sub>g</sub> + <i>w</i><sub>i</sub> · I<sub>g</sub>, &nbsp; <i>w</i><sub>d</sub> = 1.0 · <i>w</i><sub>i</sub> = 0.5<span class="spn">(1)</span></div>
     For Cardio (Progress only) minutes become equivalent sets:
     <div class="spf">S<sub>Cardio</sub> = <span class="fr"><i>cardio minutes + warm-up cardio minutes</i><i>10</i></span><span class="spn">(2)</span></div>
     Useful zones (sets per week; ticks = min–max, red outside below/above): Legs 20–40 (12/50), Chest 7–16 (4/20), Back 17–32 (9/40), Shoulders 14–30 (8/38), Arms 17–40 (9/50), Core 3–12 (0/16), Cardio 15–30 (8/45). Min = 25th percentile and max = 90th percentile of 60 balanced published programs; for Cardio, WHO guidelines of 150–300 minutes.`],
   ['Worked example',`3 sets of flat bench press: Chest 3 direct; Shoulders and Arms 3 indirect each, i.e. 3 × 0.5 = <b>1.5</b>. In the row hint one reads “0 direct ×1 + 3 indirect ×0.5 = 1.5”. With 12 sets of bench press per week, Chest reaches 12 (within 7–16) and Shoulders and Arms receive 6 “incidental” sets.`],
   ['How to read it',`The number answers “is the volume enough for this group?”, the radar chart “is it well distributed?”. A bar that is almost entirely light means the group works almost only as a by-product of multi-joint exercises. Red appears only when clearly outside, not at the boundary.`],
   ['Limitations',`The zones are calibrated on the default count (TMS catalog, 1.0 / 0.5): with other weights or with the external map they should be read with caution. They are group bands, not single-muscle bands: the literature reasons per muscle (about 10–20 sets per week for growth), and a group sums several of them. Converting cardio minutes into sets is a choice of scale, not a physiological equivalence.`]],
  b:['Schoenfeld BJ, Ogborn D, Krieger JW (2017). Dose-response relationship between weekly resistance training volume and increases in muscle mass. <i>J Sports Sci</i> 35(11):1073–1082.',
     'Schoenfeld BJ et al. (2019). Calculating set-volume for the limb muscles with the performance of multi-joint exercises. <i>Sports</i> 7(7):177.',
     'World Health Organization (2020). <i>WHO guidelines on physical activity and sedentary behaviour</i>. Geneva: WHO.',
     'TMS meta-analysis (2026): about 930 programs from StrengthLog and Muscle &amp; Strength, 60 balanced (push : pull between 0.7 and 1.4).']},

'carico-giorno':{t:'Load per day of the program',
  dove:'Weights (side panel)',
  a:`Splits the program being written across the days of the week: sets, distinct exercises and Training Load of each session, to see whether the load is concentrated on a single day.`,
  s:[['What it shows',`One row per day: a bar proportional to the session’s TL (the heaviest day is the full bar), number of sets, number of distinct exercises and TL.`],
   ['Input data',`The rows of the active program (weekly or monthly mode): day, exercise, sets, repetitions, weight, optional RIR.`],
   ['Method and formulas',`The TL of each row is the one used throughout the app:
     <div class="spf">TL = sets × reps × <i>C</i> × <span class="fr"><i>%1RM</i><i>100</i></span> × <i>f</i><span class="spn">(1)</span></div>
     with <i>C</i> the effective load (added weight + body weight × share for pull-ups, dips and leg raises), %1RM = <i>C</i> ÷ estimated 1RM × 100, <i>f</i> the exercise factor from the catalog (0–1.05). For each day, TL and sets are summed and distinct exercises are counted; the bar is TL<sub>day</sub> ÷ TL<sub>max</sub> × 100.`],
   ['Worked example',`Monday: squat 4 × 5 at 100 kg. 1RM (Epley) = 100 × (1 + 5/30) = 116.7 kg; %1RM = 85.7%; factor 0.95.
     <div class="spf">TL = 4 × 5 × 100 × 0.857 × 0.95 = 1,629</div>
     Thursday: bench press 3 × 8 at 70 kg → 1RM 88.7 kg, %1RM 78.9%, TL = 3 × 8 × 70 × 0.789 × 0.95 = 1,260. Monday is the full bar, Thursday reaches 77%.`],
   ['How to read it',`Bars of very different length indicate unbalanced sessions: a “heavy” day with twice the TL of the others concentrates fatigue and recovery. There is no right band: it depends on the scheme (full body, split).`],
   ['Limitations',`TL is a relative index of volume times intensity, not a physiological unit: it serves to compare sessions and weeks of the same athlete, not different athletes. The per-exercise factor is an estimate of systemic demand, not a measurement.`]],
  b:['McBride JM, McCaulley GO, Cormie P, Nuzzo JL, Cavill MJ, Triplett NT (2009). Comparison of methods to quantify volume during resistance exercise. <i>J Strength Cond Res</i> 23(1):106–110.',
     'Epley B (1985). <i>Poundage chart</i>. Lincoln (NE): Boyd Epley Workout.']},

'intensita':{t:'Intensity distribution by %1RM band',
  dove:'Weights (side panel) · Progress',
  a:`Classifies each set by relative intensity (%1RM) and shows how many sets fall in each band: strength, strength+hypertrophy, hypertrophy, endurance, metabolic. It describes the emphasis of the training.`,
  s:[['What it shows',`In <b>Weights</b>: the share of the sets of the program being written, by band (segmented bar). In <b>Progress</b>: the sets of the last saved week, by band (bars).`],
   ['Input data',`Weight, repetitions, optional RIR and sets of each row; for pull-ups, dips and leg raises also body weight.`],
   ['Method and formulas',`Estimated maximum with the formula chosen in the profile (default Epley):
     <div class="spf">1RM<sub>Epley</sub> = <i>C</i> × (1 + <span class="fr"><i>r</i><i>30</i></span>) · 1RM<sub>Brzycki</sub> = <i>C</i> × <span class="fr"><i>36</i><i>37 − r</i></span> (r ≤ 10) · 1RM<sub>Lombardi</sub> = <i>C</i> × r<sup>0.10</sup><span class="spn">(1)</span></div>
     <div class="spf">%1RM = <span class="fr"><i>C</i><i>1RM</i></span> × 100<span class="spn">(2)</span></div>
     where <i>r</i> = repetitions (+ RIR if “RIR in calculations” is on). Bands: Strength ≥ 90%, Strength+Hyp 80–89%, Hypertrophy 70–79%, Endurance 60–69%, Metabolic 50–59%; below 50% the set is not counted.`],
   ['Worked example',`Squat 4 × 5 at 100 kg → %1RM 85.7% → <b>Strength+Hyp</b>, 4 sets. Bench press 3 × 8 at 70 kg → %1RM 78.9% → <b>Hypertrophy</b>, 3 sets. Shares: 57% and 43%. With RIR 2 declared on the bench press, <i>r</i> = 10 → 1RM 93.3 kg → %1RM 75%: it remains Hypertrophy.`],
   ['How to read it',`A week entirely in one band is monotonous; strength programs shift the weight toward the first two bands, hypertrophy programs toward the middle. The bands are a reading, not a target.`],
   ['Limitations',`%1RM is computed on the maximum estimated from the same set: with many repetitions (above 10–12) the formulas lose precision and tend to underestimate intensity. RIR is a subjective estimate. The band thresholds are didactic conventions, with wide overlap in effects.`]],
  b:['Epley B (1985). <i>Poundage chart</i>. Boyd Epley Workout.',
     'Brzycki M (1993). Strength testing — predicting a one-rep max from reps-to-fatigue. <i>J Phys Educ Recreat Dance</i> 64(1):88–90.',
     'Lombardi VP (1989). <i>Beginning weight training</i>. Dubuque: W.C. Brown.',
     'Zourdos MC et al. (2016). Novel resistance training-specific RPE scale measuring repetitions in reserve. <i>J Strength Cond Res</i> 30(1):267–275.',
     'Haff GG, Triplett NT (2016). <i>Essentials of Strength Training and Conditioning</i>, 4th ed. Champaign: Human Kinetics.']},

'tl':{t:'Total Training Load and moving average',
  dove:'Progress',
  a:`Training Load (TL) summarizes a week of weight-training work in a single number, combining volume and relative intensity. The moving average over the last four weeks represents the load the athlete is accustomed to (chronic load).`,
  s:[['What it shows',`A line with the TL of each saved week and a second line with the 4-week moving average.`],
   ['Input data',`The History rows (excluding ★ max tests), filtered by Training Set if chosen in “Data to analyze”.`],
   ['Method and formulas',`<div class="spf">TL<sub>week</sub> = Σ<sub>rows</sub> sets × reps × <i>C</i> × <span class="fr"><i>%1RM</i><i>100</i></span> × <i>f</i><span class="spn">(1)</span></div>
     Since %1RM = <i>C</i>/1RM, the product <i>C</i> × %1RM/100 equals <i>C</i>²/1RM: for equal repetitions, work close to the maximum weighs more.
     <div class="spf">Chronic<sub>t</sub> = <span class="fr"><i>Σ TL of weeks t−3 … t</i><i>n</i></span><span class="spn">(2)</span></div>
     Weeks are <b>calendar</b> weeks: a week with no records counts as zero; <i>n</i> = 4, but at the start of the history only the weeks already elapsed count. Anyone who records at a pace other than weekly (median distance between two saves greater than 1), or filters a Training Set, gets the average of the last 4 records.`],
   ['Worked example',`Week with squat 4 × 5 at 100 kg (TL 1,629) and bench press 3 × 8 at 70 kg (TL 1,260): TL = 2,889. If the three previous weeks were 2,700, 2,800 and 2,650, the moving average is (2,700 + 2,800 + 2,650 + 2,889) / 4 = 2,760.`],
   ['How to read it',`The trend matters, not the absolute value: gradual growth with the moving average following indicates sustainable progression; a TL well above the average is a load jump (see ACWR); a prolonged drop is a deload or a break.`],
   ['Limitations',`TL does not distinguish between muscle groups nor measure perceived fatigue. It depends on the 1RM formula and on the exercise factor, which is an estimate. It is not comparable between athletes.`]],
  b:['Haff GG (2010). Quantifying workloads in resistance training: a brief review. <i>Professional Strength &amp; Conditioning</i> (UKSCA) 19:31–40.',
     'McBride JM et al. (2009). Comparison of methods to quantify volume during resistance exercise. <i>J Strength Cond Res</i> 23(1):106–110.']},

'acwr':{t:'Acute:chronic workload ratio (ACWR)',
  dove:'Progress',
  a:`The ACWR compares the load of the last week with the average of the last four. Values between 0.8 and 1.3 indicate a load consistent with habit; high values signal a sudden increase, associated in the literature with a greater risk of overload.`,
  s:[['What it shows',`A line with the ACWR of each week and a green band between 0.8 and 1.3. In the “Signals” above the charts: above 1.5 “very high load”, below 0.8 “low load”.`],
   ['Input data',`The weekly TL from History (see “Total Training Load”).`],
   ['Method and formulas',`<div class="spf">ACWR<sub>t</sub> = <span class="fr"><i>TL<sub>t</sub></i><i>Chronic<sub>t</sub></i></span>, &nbsp; Chronic<sub>t</sub> = <span class="fr"><i>Σ<sub>k=t−3…t</sub> TL<sub>k</sub></i><i>n</i></span><span class="spn">(1)</span></div>
     The chronic load includes the current week (“coupled” model) and counts calendar weeks: those without training count as zero. With a non-weekly recording pace, or when filtering a Training Set, the last 4 records are used.`],
   ['Worked example',`TL of the last four weeks: 10,000, 11,000, 10,500, 14,000. Chronic = 45,500 / 4 = 11,375; ACWR = 14,000 / 11,375 = <b>1.23</b> (in zone). After three weeks off (0, 0, 0) and a return at 14,000: chronic = 3,500, ACWR = <b>4.0</b> → very-high-load signal, because the athlete is no longer accustomed to that volume.`],
   ['How to read it',`It is a signal of too rapid progression, not a diagnosis. Above 1.5 it is advisable to consider a deload or a more gradual increase; below 0.8 for several weeks the load is declining (intended in a deload, otherwise to be reviewed).`],
   ['Limitations',`The ACWR has been criticized on statistical grounds (coupling between numerator and denominator, instability with low chronic loads) and the relationship with injuries has been shown mainly in team sports. The thresholds 0.8–1.3 and 1.5 are indicative.`]],
  b:['Gabbett TJ (2016). The training–injury prevention paradox: should athletes be training smarter and harder? <i>Br J Sports Med</i> 50(5):273–280.',
     'Hulin BT, Gabbett TJ, Lawson DW, Caputi P, Sampson JA (2016). The acute:chronic workload ratio predicts injury. <i>Br J Sports Med</i> 50(4):231–236.',
     'Impellizzeri FM et al. (2020). Acute:chronic workload ratio: conceptual issues and fundamental pitfalls. <i>Int J Sports Physiol Perform</i> 15(6):907–913.']},

'tonnellaggio':{t:'Weekly tonnage',
  dove:'Progress',
  a:`Tonnage (volume load) is the total mass lifted in a week: sets × repetitions × load. It is the simplest and most widespread volume measure.`,
  s:[['What it shows',`A line with the total kilograms lifted in each saved week.`],
   ['Input data',`Sets, repetitions and weight of the History rows (excluding ★ tests); for pull-ups, dips and leg raises also the body weight of the week.`],
   ['Method and formulas',`<div class="spf">Tonnage = Σ<sub>rows</sub> sets × reps × <i>C</i>, &nbsp; <i>C</i> = added weight + body weight × share<span class="spn">(1)</span></div>
     The share is 1 for pull-ups and dips, 0.40 (men) or 0.42 (women) for straight-leg raises, 0.25 with bent knees, 0 for the other exercises. Body weight is the one measured in the same week, otherwise the nearest.`],
   ['Worked example',`Squat 4 × 5 at 100 kg = 2,000 kg; bench press 3 × 8 at 70 kg = 1,680 kg; pull-ups 3 × 8 with 10 kg added weight and a body weight of 80 kg = 3 × 8 × 90 = 2,160 kg. Total = <b>5,840 kg</b>.`],
   ['How to read it',`It grows with volume and with load. Unlike TL it does not take relative intensity into account: 10 light repetitions and 10 heavy ones at the same total weight count the same. Useful for following volume in accumulation phases.`],
   ['Limitations',`It sums very different exercises (one deadlift repetition and one curl repetition count for the kilos lifted), so it should be compared only with itself over time.`]],
  b:['McBride JM et al. (2009). Comparison of methods to quantify volume during resistance exercise. <i>J Strength Cond Res</i> 23(1):106–110.',
     'de Leva P (1996). Adjustments to Zatsiorsky-Seluyanov’s segment inertia parameters. <i>J Biomech</i> 29(9):1223–1230.']},

'delta-tl':{t:'Percentage change in Training Load',
  dove:'Progress',
  a:`Measures how much TL changes from one saved week to the previous one, as a percentage. It highlights jumps and drops in load more clearly than the absolute curve.`,
  s:[['What it shows',`A line with the percentage change in TL relative to the previous record.`],
   ['Input data',`The weekly TL (see “Total Training Load”).`],
   ['Method and formulas',`<div class="spf">ΔTL%<sub>t</sub> = ( <span class="fr"><i>TL<sub>t</sub></i><i>TL<sub>t−1</sub></i></span> − 1 ) × 100<span class="spn">(1)</span></div>
     where <i>t</i>−1 is the previous record (not necessarily the previous calendar week). The first point has no comparison.`],
   ['Worked example',`TL 2,889 → 3,100: ΔTL% = (3,100 / 2,889 − 1) × 100 = <b>+7.3%</b>. TL 3,100 → 2,500: −19.4%.`],
   ['How to read it',`Contained oscillations (about ±3–10%) indicate regular progression; large positive peaks are load jumps, negative peaks are deloads or incomplete weeks.`],
   ['Limitations',`If several weeks pass between two records the comparison ignores them: in that case the ACWR on calendar weeks is more informative.`]],
  b:['Gabbett TJ (2016). The training–injury prevention paradox. <i>Br J Sports Med</i> 50(5):273–280.']},

'srpe':{t:'Weekly internal load (session-RPE)',
  dove:'Progress (with Session-RPE enabled in the profile)',
  a:`Internal load estimates perceived effort: for each session the RPE (0–10) is multiplied by the duration in minutes, yielding arbitrary units (AU). It complements the external load (TL), which measures the work done.`,
  s:[['What it shows',`A line with the weekly sum of the AU of the weight-training sessions.`],
   ['Input data',`RPE and minutes per day entered in the Weights tab and saved in History (by enabling “Session-RPE” in the personal details).`],
   ['Method and formulas',`<div class="spf">Load<sub>session</sub> = RPE × minutes &nbsp;[AU] · Load<sub>week</sub> = Σ<sub>days</sub> Load<sub>session</sub><span class="spn">(1)</span></div>`],
   ['Worked example',`Monday RPE 7 for 60 min = 420 AU; Wednesday RPE 8 for 70 min = 560 AU; Friday RPE 6 for 50 min = 300 AU. Week = <b>1,280 AU</b>.`],
   ['How to read it',`If internal load rises more than external load, the same amount of work costs more effort (tiredness, little recovery, stress). It is read together with monotony, strain and “Internal vs external”.`],
   ['Limitations',`RPE is subjective and depends on when it is collected (Foster recommends about 30 minutes after the session). AU are not comparable between different people.`]],
  b:['Foster C, Florhaug JA, Franklin J et al. (2001). A new approach to monitoring exercise training. <i>J Strength Cond Res</i> 15(1):109–115.',
     'Haddad M, Stylianides G, Djaoui L, Dellal A, Chamari K (2017). Session-RPE method for training load monitoring: validity, ecological usefulness, and influencing factors. <i>Front Neurosci</i> 11:612.']},

'monotonia':{t:'Training monotony',
  dove:'Progress (with Session-RPE enabled)',
  a:`Foster’s monotony measures how uniform the week is: it is the ratio between the mean daily load and its standard deviation. High values indicate days that are all alike, with little alternating recovery.`,
  s:[['What it shows',`A line with the weekly monotony and a green band up to 2.`],
   ['Input data',`The load of each day (RPE × minutes) over the 7 days of the week; days without training count as 0.`],
   ['Method and formulas',`<div class="spf">Monotony = <span class="fr"><i>x̄</i><i>σ</i></span>, &nbsp; x̄ = <span class="fr"><i>Σ<sub>d=1…7</sub> x<sub>d</sub></i><i>7</i></span>, &nbsp; σ = √( <span class="fr"><i>Σ (x<sub>d</sub> − x̄)²</i><i>7</i></span> )<span class="spn">(1)</span></div>
     Population standard deviation over the 7 days, rest days included; if σ = 0 the monotony is undefined.`],
   ['Worked example',`Loads [420, 0, 560, 0, 300, 0, 0]: x̄ = 182.9; σ = 222.3; monotony = <b>0.82</b>. Five nearly equal days (420, 400, 410, 430, 420) and two rest days: monotony = <b>1.58</b>.`],
   ['How to read it',`Above 2, especially with a high load, Foster observed more episodes of illness and overtraining: it is advisable to alternate hard and light days or add a rest day. In the “Signals” the app warns when monotony exceeds 2.`],
   ['Limitations',`With few recorded days the estimate is unstable; the threshold of 2 comes from observations on endurance athletes and should be taken as an indication.`]],
  b:['Foster C (1998). Monitoring training in athletes with reference to overtraining syndrome. <i>Med Sci Sports Exerc</i> 30(7):1164–1168.',
     'Foster C et al. (2001). A new approach to monitoring exercise training. <i>J Strength Cond Res</i> 15(1):109–115.']},

'strain':{t:'Strain (load × monotony)',
  dove:'Progress (with Session-RPE enabled)',
  a:`Foster’s strain combines the quantity and uniformity of internal load: a heavy and monotonous week produces a high strain. It is the index that Foster associated most directly with illness and overtraining.`,
  s:[['What it shows',`A line with the strain of each week.`],
   ['Input data',`Weekly internal load and monotony (see the respective notes).`],
   ['Method and formulas',`<div class="spf">Strain = Load<sub>week</sub> × Monotony<span class="spn">(1)</span></div>`],
   ['Worked example',`Load 1,280 AU, monotony 0.82 → strain = <b>1,053</b>. Load 2,080 AU over five similar days (monotony 1.58) → strain = <b>3,285</b>: three times as much with 60% more load.`],
   ['How to read it',`It should be followed over time: isolated peaks after stable weeks signal accumulated fatigue. There is no universal threshold.`],
   ['Limitations',`It inherits the limitations of RPE and monotony; the units are arbitrary and individual.`]],
  b:['Foster C (1998). Monitoring training in athletes with reference to overtraining syndrome. <i>Med Sci Sports Exerc</i> 30(7):1164–1168.']},

'interno-esterno':{t:'Internal load versus external load',
  dove:'Progress (with Session-RPE enabled)',
  a:`Compares the trend of internal load (sRPE) and external load (TL) on a common scale, setting both to 100 in the first week with data. If the two curves diverge, the perceived cost of the work changes.`,
  s:[['What it shows',`Two indexed lines: sRPE and TL.`],
   ['Input data',`Weekly internal load (RPE × minutes) and weekly TL.`],
   ['Method and formulas',`<div class="spf">Index<sub>t</sub> = <span class="fr"><i>value<sub>t</sub></i><i>value<sub>base</sub></i></span> × 100<span class="spn">(1)</span></div>
     The base of each series is its first non-zero value.`],
   ['Worked example',`First week: sRPE 1,000 AU, TL 10,000 → both 100. Fifth week: sRPE 1,300, TL 11,000 → 130 and 110: perceived effort has grown twice as much as the work.`],
   ['How to read it',`Internal above external: the same work weighs more (fatigue, sleep, stress, little recovery). Internal below external: the athlete tolerates the load better (adaptation).`],
   ['Limitations',`The index depends on the base week: if it is anomalous, the whole curve is affected.`]],
  b:['Impellizzeri FM, Marcora SM, Coutts AJ (2019). Internal and external training load: 15 years on. <i>Int J Sports Physiol Perform</i> 14(2):270–273.',
     'Foster C et al. (2001). A new approach to monitoring exercise training. <i>J Strength Cond Res</i> 15(1):109–115.']},

'tl-gruppo':{t:'Training Load per muscle group',
  dove:'Progress',
  a:`Breaks down the weekly TL across muscle groups, to see over time which regions receive more load and which are neglected.`,
  s:[['What it shows',`One line per group with the weekly TL.`],
   ['Input data',`The History rows with their group (the exercise’s main group, saved in the row).`],
   ['Method and formulas',`<div class="spf">TL<sub>g,week</sub> = Σ<sub>rows of group g</sub> TL<sub>row</sub><span class="spn">(1)</span></div>
     Here the TL goes <b>entirely</b> to the exercise’s main group: it is not split between primary and secondary muscles as the sets are.`],
   ['Worked example',`Squat (Legs) TL 1,629, bench press (Chest) TL 1,260: Legs 1,629, Chest 1,260, no TL to Shoulders and Arms even though they work as by-products.`],
   ['How to read it',`A line that falls for weeks indicates a group set aside; a group that dominates the total TL indicates an unbalanced program. For fine balance, use the radar chart.`],
   ['Limitations',`Attribution to a single group overestimates the main group of multi-joint exercises and underestimates the others.`]],
  b:['Haff GG (2010). Quantifying workloads in resistance training: a brief review. <i>Professional Strength &amp; Conditioning</i> (UKSCA) 19:31–40.']},

'progressione':{t:'Progression of the estimated maximum',
  dove:'Progress · Exercises (exercise card)',
  a:`Tracks over time the estimated maximum (1RM) of an exercise, derived from the recorded sets, together with the maximum load used. It is the most direct indicator of strength in that movement.`,
  s:[['What it shows',`For each week in which the exercise was done: the highest estimated 1RM and the highest weight (in Exercises only the 1RM).`],
   ['Input data',`Weight, repetitions and optional RIR of the History rows for that exercise; body weight for bodyweight exercises.`],
   ['Method and formulas',`<div class="spf">1RM = <i>C</i> × (1 + <span class="fr"><i>r</i><i>30</i></span>) &nbsp;(Epley; or Brzycki, Lombardi or the mean of the three)<span class="spn">(1)</span></div>
     <i>C</i> = added weight + body weight × share; <i>r</i> = repetitions (+ RIR if on). For pull-ups, dips and leg raises the added weight is <b>shown</b>: 1RM<sub>shown</sub> = 1RM − body weight × share. For each week the maximum among the rows is taken.`],
   ['Worked example',`Pull-ups 3 × 6 with 15 kg added weight, body weight 80 kg: <i>C</i> = 95 kg, 1RM = 95 × (1 + 6/30) = 114 kg; the display reads <b>34 kg</b> (“how much you could hang for a single”). Squat 5 × 5 at 100 kg → 116.7 kg.`],
   ['How to read it',`A positive slope indicates strength gain; if the exercise’s Training Load stays flat for 3 or more programs, the exercise appears among the “Signals” as a stall. Deload weeks lower the point without strength having declined.`],
   ['Limitations',`The formulas are estimates: they are more accurate between 2 and 10 repetitions; with long sets the error grows. Execution style and fatigue change the value.`]],
  b:['Epley B (1985). <i>Poundage chart</i>. Boyd Epley Workout.',
     'Brzycki M (1993). Strength testing — predicting a one-rep max from reps-to-fatigue. <i>J Phys Educ Recreat Dance</i> 64(1):88–90.',
     'LeSuer DA, McCormick JH, Mayhew JL, Wasserstein RL, Arnold MD (1997). The accuracy of prediction equations for estimating 1-RM performance. <i>J Strength Cond Res</i> 11(4):211–213.']},

'storico-carico':{t:'Load per week in History',
  dove:'History (side panel)',
  a:`Summarizes the Training Load of the rows currently filtered in History, week by week, to see at a glance how the load has been distributed.`,
  s:[['What it shows',`The last 12 weeks (from the most recent), each with a bar proportional to its TL; at the top the number of weeks and the mean TL.`],
   ['Input data',`The History rows that pass the table filters (exercise, group, program), excluding ★ tests.`],
   ['Method and formulas',`<div class="spf">TL<sub>week</sub> = Σ<sub>filtered rows</sub> TL<sub>row</sub> · mean TL = <span class="fr"><i>Σ<sub>week</sub> TL<sub>week</sub></i><i>number of weeks</i></span><span class="spn">(1)</span></div>
     The bar is TL<sub>week</sub> ÷ TL<sub>max</sub> of the 12 shown.`],
   ['Worked example',`Filtering “Barbell squat”: three weeks with TL 1,629, 1,800, 1,700 → mean 1,710; the second is the full bar.`],
   ['How to read it',`With a filter on an exercise it becomes that exercise’s load trend; without filters it is the total load.`],
   ['Limitations',`Weeks without rows do not appear (they do not count as zero as in the ACWR).`]],
  b:['McBride JM et al. (2009). Comparison of methods to quantify volume during resistance exercise. <i>J Strength Cond Res</i> 23(1):106–110.']},

'storico-esercizi':{t:'Exercises that weigh most on the load',
  dove:'History (side panel)',
  a:`Ranks the exercises of the filtered rows by the share of Training Load they carry, to understand on which movements the work is concentrated.`,
  s:[['What it shows',`The 7 exercises with the most TL, with a bar and the percentage of the total TL of the filtered rows.`],
   ['Input data',`The filtered History rows (excluding tests).`],
   ['Method and formulas',`<div class="spf">Share<sub>ex</sub> = <span class="fr"><i>Σ TL of the exercise’s rows</i><i>Σ TL of all filtered rows</i></span> × 100<span class="spn">(1)</span></div>`],
   ['Worked example',`On a total TL of 30,000: squat 9,000 (30%), bench press 6,000 (20%), deadlift 4,500 (15%).`],
   ['How to read it',`An exercise that alone exceeds one third of the load dominates the programming; useful for deciding on variants or redistributing.`],
   ['Limitations',`TL favors exercises with high loads and a high factor: isolation exercises always come out small even if important.`]],
  b:['Haff GG (2010). Quantifying workloads in resistance training: a brief review. <i>Professional Strength &amp; Conditioning</i> (UKSCA) 19:31–40.']},

'cardio-settimana':{t:'Cardio activity minutes against the guidelines',
  dove:'Cardio (side panel)',
  a:`Compares the cardio minutes of the current week with the World Health Organization guidelines for adults: 150–300 minutes per week of moderate aerobic activity.`,
  s:[['What it shows',`The minutes of the current ISO week, a bar that is full at 300 minutes with a tick at 150, and the label “below”, “within” or “above the recommended zone”.`],
   ['Input data',`Duration of the activities recorded in the Cardio tab dated in the current week (Monday to Sunday).`],
   ['Method and formulas',`<div class="spf">Minutes<sub>week</sub> = Σ duration · Bar = min(100, Minutes<sub>week</sub> ÷ 300 × 100)<span class="spn">(1)</span></div>
     Status: below 150 → below the zone; 150–300 → within the zone; above 300 → above.`],
   ['Worked example',`Running 45 min, cycling 60 min, swimming 30 min = <b>135 min</b>: bar at 45%, before the tick, “below the recommended zone”. With another 20 minutes you enter the zone.`],
   ['How to read it',`The zone is a minimum for health, not a limit: above 300 minutes the benefits continue, but recovery needs to be managed.`],
   ['Limitations',`The WHO alternatively indicates 75–150 minutes of vigorous activity: the app counts all minutes as moderate, so it underestimates those who do intense training.`]],
  b:['World Health Organization (2020). <i>WHO guidelines on physical activity and sedentary behaviour</i>. Geneva: WHO.',
     'Bull FC et al. (2020). World Health Organization 2020 guidelines on physical activity and sedentary behaviour. <i>Br J Sports Med</i> 54(24):1451–1462.']},

'cardio-carico':{t:'Internal load of cardio activities (sRPE)',
  dove:'Cardio (side panel) · Progress (cardio by sport)',
  a:`Cardio activities have no sets and loads: their load is measured as internal load, session RPE times duration, in arbitrary units (AU), the same method used for weight-training sessions.`,
  s:[['What it shows',`In the Cardio panel: the last 8 weeks with AU and minutes. In Progress: the sRPE of each session of the chosen sport.`],
   ['Input data',`RPE (0–10) and duration in minutes of each activity.`],
   ['Method and formulas',`<div class="spf">sRPE<sub>session</sub> = round(RPE × minutes) &nbsp;[AU]<span class="spn">(1)</span></div>
     <div class="spf">sRPE<sub>week</sub> = Σ sRPE<sub>session</sub><span class="spn">(2)</span></div>
     In the panel the bar is proportional to the AU (or to the minutes if the RPEs are missing).`],
   ['Worked example',`Running 45 minutes at RPE 6 = <b>270 AU</b>; cycling 60 minutes at RPE 4 = 240 AU; week = 510 AU over 105 minutes.`],
   ['How to read it',`For equal minutes, higher AU mean harder sessions. Useful for balancing intense and light sessions and for mentally adding the cardio load to that of the weights.`],
   ['Limitations',`RPE is subjective; cardio AU do not enter the weights’ TL or ACWR.`]],
  b:['Foster C et al. (2001). A new approach to monitoring exercise training. <i>J Strength Cond Res</i> 15(1):109–115.']},

'cardio-sport':{t:'Breakdown of minutes across sports',
  dove:'Cardio (side panel)',
  a:`Shows how the minutes of all recorded cardio activities are divided among the different sports.`,
  s:[['What it shows',`Up to 8 sports, with a bar, hours and percentage of the total minutes.`],
   ['Input data',`Type and duration of all the activities in the Cardio tab.`],
   ['Method and formulas',`<div class="spf">Share<sub>sport</sub> = <span class="fr"><i>Σ minutes of the sport</i><i>Σ minutes of all activities</i></span> × 100<span class="spn">(1)</span></div>`],
   ['Worked example',`Running 600 min, cycling 300, swimming 100: running 10.0 h (60%), cycling 5.0 h (30%), swimming 1.7 h (10%).`],
   ['How to read it',`It helps to see the variety of aerobic training and how much the main sport weighs.`],
   ['Limitations',`It considers the whole history, not just the recent period; it does not take intensity into account.`]],
  b:['World Health Organization (2020). <i>WHO guidelines on physical activity and sedentary behaviour</i>. Geneva: WHO.']},

'cardio-fc':{t:'Mean heart rate per session',
  dove:'Progress (cardio by sport)',
  a:`Tracks the mean heart rate of the sessions of a sport. With resting and maximum heart rate it allows estimating the cardiovascular load (Banister’s TRIMP).`,
  s:[['What it shows',`A line with the mean HR (beats per minute) of each session of the chosen sport.`],
   ['Input data',`Mean HR of the session (entered or imported from the watch file); resting HR and maximum HR from the profile, or maximum HR estimated from age.`],
   ['Method and formulas',`Heart rate reserve used (Karvonen) and TRIMP (Banister), shown in the activities table:
     <div class="spf">HRr = <span class="fr"><i>HR<sub>mean</sub> − HR<sub>rest</sub></i><i>HR<sub>max</sub> − HR<sub>rest</sub></i></span> (between 0 and 1)<span class="spn">(1)</span></div>
     <div class="spf">TRIMP = minutes × HRr × <i>y</i>, &nbsp; <i>y</i> = 0.64·e<sup>1.92·HRr</sup> (men) · 0.86·e<sup>1.67·HRr</sup> (women)<span class="spn">(2)</span></div>
     <div class="spf">HR<sub>max</sub> estimated = 208 − 0.7 × age (Tanaka)<span class="spn">(3)</span></div>
     Default resting HR 60 if not specified. The session peak counts only if it exceeds the known or estimated maximum HR.`],
   ['Worked example',`Man, running 45 minutes at mean HR 150, rest 60, maximum 190: HRr = 90/130 = 0.692; <i>y</i> = 0.64 × e<sup>1.329</sup> = 2.418; TRIMP = 45 × 0.692 × 2.418 = <b>75</b>.`],
   ['How to read it',`For equal pace or speed, a mean HR that falls over time indicates better aerobic efficiency; one that rises, fatigue or heat.`],
   ['Limitations',`HR is affected by temperature, hydration, caffeine and stress. The Tanaka formula has an error of about ±10 bpm: better to enter the measured maximum HR.`]],
  b:['Banister EW (1991). Modeling elite athletic performance. In: MacDougall JD, Wenger HA, Green HJ (eds.), <i>Physiological Testing of the High-Performance Athlete</i>. Champaign: Human Kinetics, 403–424.',
     'Karvonen MJ, Kentala E, Mustala O (1957). The effects of training on heart rate: a longitudinal study. <i>Ann Med Exp Biol Fenn</i> 35(3):307–315.',
     'Tanaka H, Monahan KD, Seals DR (2001). Age-predicted maximal heart rate revisited. <i>J Am Coll Cardiol</i> 37(1):153–156.']},

'cardio-distanza':{t:'Distance per session',
  dove:'Progress (cardio by sport)',
  a:`Tracks the kilometers covered in each session of sports that have a distance (running, walking, cycling, swimming, rowing, cross-country skiing…).`,
  s:[['What it shows',`A line with the distance in km of each session of the chosen sport.`],
   ['Input data',`The session’s distance field, entered by hand or imported from the watch file.`],
   ['Method and formulas',`Recorded value, without transformations: <div class="spf">y<sub>session</sub> = distance [km]</div>`],
   ['Worked example',`Runs of 5.0 – 6.2 – 7.5 – 8.0 km: the line shows the increase in the volume of the outings.`],
   ['How to read it',`For endurance sports distance is the main volume measure; gradual weekly increases reduce the risk of overload.`],
   ['Limitations',`GPS distance has errors of a few percentage points; on a treadmill it depends on the machine’s calibration.`]],
  b:['Nielsen RO et al. (2014). Excessive progression in weekly running distance and risk of running-related injuries. <i>J Orthop Sports Phys Ther</i> 44(10):739–747.']},

'cardio-passo':{t:'Mean pace (minutes per kilometer)',
  dove:'Progress (cardio by sport: running, treadmill, walking)',
  a:`Mean pace is the time taken to cover one kilometer. The lower it is, the faster you are.`,
  s:[['What it shows',`A line with the mean pace of each session, in minutes per kilometer.`],
   ['Input data',`Duration and distance of the session.`],
   ['Method and formulas',`<div class="spf">Pace = <span class="fr"><i>duration [min]</i><i>distance [km]</i></span> &nbsp;[min/km]<span class="spn">(1)</span></div>
     In the tables it is shown in minutes and seconds (m:ss).`],
   ['Worked example',`45 minutes for 7.5 km: 45 / 7.5 = 6.00 → <b>6:00 /km</b>. 42 minutes for 7.5 km → 5:36 /km.`],
   ['How to read it',`A falling line indicates faster sessions; it should be read together with mean HR and distance (the same pace over a longer distance is an improvement).`],
   ['Limitations',`It is a mean value: it does not distinguish interval work, climbs and pauses.`]],
  b:['Daniels J (2013). <i>Daniels’ Running Formula</i>, 3rd ed. Champaign: Human Kinetics.']},

'cardio-velocita':{t:'Mean speed',
  dove:'Progress (cardio by sport: cycling, stationary bike, cross-country skiing)',
  a:`Mean speed is the distance covered in one hour: for sports where one reasons in km/h rather than in pace.`,
  s:[['What it shows',`A line with the mean speed of each session in km/h.`],
   ['Input data',`Duration and distance of the session.`],
   ['Method and formulas',`<div class="spf">Speed = <span class="fr"><i>distance [km]</i><i>duration [min] ÷ 60</i></span> &nbsp;[km/h]<span class="spn">(1)</span></div>`],
   ['Worked example',`30 km in 75 minutes: 30 / 1.25 = <b>24.0 km/h</b>.`],
   ['How to read it',`A speed that rises for the same route and HR indicates improvement; it should be compared on similar outings (wind and elevation change it a lot).`],
   ['Limitations',`Mean over the whole session, stops included if recorded in the total time.`]],
  b:['Jeukendrup AE, Martin J (2001). Improving cycling performance: how should we spend our time and money. <i>Sports Med</i> 31(7):559–569.']},

'cardio-dislivello':{t:'Elevation gain per session',
  dove:'Progress (cardio by outdoor sport)',
  a:`Elevation gain (D+) is the sum of the meters climbed in a session: it measures how demanding the route was vertically.`,
  s:[['What it shows',`A line with the meters of D+ of each session of the chosen sport.`],
   ['Input data',`The session’s elevation field (entered or from the GPS file).`],
   ['Method and formulas',`Recorded value: <div class="spf">D+ = Σ climbs [m]</div>`],
   ['Worked example',`Hilly run of 10 km with 250 m of D+; bike ride of 40 km with 600 m.`],
   ['How to read it',`It explains why sessions with high D+ have a slower pace and higher HR: it should be read together with those charts.`],
   ['Limitations',`D+ from barometric or satellite GPS differs by even 10–20% between devices.`]],
  b:['Minetti AE et al. (2002). Energy cost of walking and running at extreme uphill and downhill slopes. <i>J Appl Physiol</i> 93(3):1039–1046.']},

'composizione':{t:'Body composition',
  dove:'Body',
  a:`Breaks down current body weight into muscle mass, fat mass, bone mass and remainder, from the entered measurements (typically from a bioimpedance scale).`,
  s:[['What it shows',`A bar divided into four parts and the values in kg and percentage; at the bottom the weight change from the first recorded measurement.`],
   ['Input data',`Weight, fat-mass fraction (e.g. 0.145), muscle mass and bone mass in kg, from the Body tab.`],
   ['Method and formulas',`<div class="spf">Fat = weight × fat fraction · Rest = weight − fat − muscle − bone (never below zero)<span class="spn">(1)</span></div>
     Each part as a percentage: value ÷ weight × 100. Lean mass (in Body) is weight − fat mass.`],
   ['Worked example',`Weight 80 kg, fat 0.15, muscle 60 kg, bone 3.2 kg: fat = 12 kg (15%); muscle 75%; bone 4%; rest 4.8 kg (6%).`],
   ['How to read it',`In a recomposition weight may stay still while fat mass falls and muscle mass rises: look at the parts, not only the total.`],
   ['Limitations',`Bioimpedance depends on hydration, meals and time of measurement (error of a few percentage points): compare measurements taken under the same conditions. The “muscle mass” of scales includes water and other lean tissues.`]],
  b:['Kyle UG et al. (2004). Bioelectrical impedance analysis — part I: review of principles and methods. <i>Clin Nutr</i> 23(5):1226–1243.']},

'peso':{t:'Body weight trend',
  dove:'Body',
  a:`Tracks body weight measurement after measurement. It is the simplest data for following a bulk, maintenance or cut phase.`,
  s:[['What it shows',`A line with the weight of each measurement saved in the measurement history, dated by week.`],
   ['Input data',`The weight saved with “💾 Save measurements to History”.`],
   ['Method and formulas',`Recorded value: <div class="spf">y<sub>week</sub> = weight [kg]</div> The weight of each week is also used for the load of bodyweight exercises of that week.`],
   ['Worked example',`80.0 → 80.4 → 80.9 → 81.1 kg in 4 weeks: about +0.37 kg per week, a typical pace for a bulk phase.`],
   ['How to read it',`Trends over several weeks matter: daily fluctuations (water, glycogen, salt) reach 1–2 kg. Weigh yourself under the same conditions (morning, fasted).`],
   ['Limitations',`Weight does not distinguish fat from lean mass: read it together with composition.`]],
  b:['Hall KD et al. (2011). Quantification of the effect of energy imbalance on bodyweight. <i>Lancet</i> 378(9793):826–837.']},

'bmi':{t:'Body mass index (BMI)',
  dove:'Body',
  a:`BMI relates weight to the square of height. It is a population indicator for classifying underweight, normal weight, overweight and obesity.`,
  s:[['What it shows',`A line with the BMI of each saved measurement; in the card at the top the current class.`],
   ['Input data',`Weight of the measurement and height from the profile.`],
   ['Method and formulas',`<div class="spf">BMI = <span class="fr"><i>weight [kg]</i><i>height [m]²</i></span><span class="spn">(1)</span></div>
     WHO classes: below 18.5 underweight; 18.5–24.9 normal weight; 25–29.9 overweight; from 30 obesity.`],
   ['Worked example',`80 kg and 1.80 m: 80 / 3.24 = <b>24.7</b> → normal weight.`],
   ['How to read it',`For those who train with weights BMI rises with muscle mass: an “overweight” BMI with low fat mass does not indicate excess fat.`],
   ['Limitations',`It does not distinguish fat and muscle, nor fat distribution; it is not suitable for assessing muscular athletes.`]],
  b:['World Health Organization (2000). <i>Obesity: preventing and managing the global epidemic</i>. WHO Technical Report Series 894. Geneva: WHO.']},

'massa':{t:'Lean mass and muscle mass over time',
  dove:'Body',
  a:`Two lines track lean mass (everything that is not fat) and estimated muscle mass, to see whether the weight gained or lost is lean tissue.`,
  s:[['What it shows',`Lean mass and muscle mass (kg) for each saved measurement.`],
   ['Input data',`Weight and fat-mass fraction (for lean mass); entered muscle mass.`],
   ['Method and formulas',`<div class="spf">Lean mass = weight × (1 − fat fraction)<span class="spn">(1)</span></div>
     Muscle mass is the entered value (from the scale), not calculated.`],
   ['Worked example',`80 kg with fat 0.15 → lean 68.0 kg. Two months later 81 kg with fat 0.14 → lean 69.7 kg: +1.7 kg of lean mass with +1 kg of weight.`],
   ['How to read it',`In a bulk one looks for lean mass rising more than weight; in a cut, lean mass stable while weight falls.`],
   ['Limitations',`The same as bioimpedance: small changes (under 1 kg) are within measurement error.`]],
  b:['Kyle UG et al. (2004). Bioelectrical impedance analysis — part I. <i>Clin Nutr</i> 23(5):1226–1243.']},

'energia':{t:'Plan energy versus requirement',
  dove:'Nutrition (side panel)',
  a:`Compares the daily calories of the active-phase meal plan with the estimated requirement, and derives the surplus or deficit.`,
  s:[['What it shows',`Two bars (plan and requirement) on the same scale and the difference in kcal per day: green if within ±50 kcal.`],
   ['Input data',`Foods and grams of the plan; nutritional values per 100 g from the database (Swiss USAV, Ciqual); basal metabolic rate and activity level (PAL) from the Body tab.`],
   ['Method and formulas',`<div class="spf">kcal<sub>food</sub> = kcal<sub>100 g</sub> × <span class="fr"><i>grams</i><i>100</i></span> · Plan = Σ kcal<sub>food</sub><span class="spn">(1)</span></div>
     <div class="spf">Requirement = basal metabolic rate × PAL · Balance = Plan − Requirement<span class="spn">(2)</span></div>`],
   ['Worked example',`Basal 1,800 kcal × PAL 1.55 = 2,790 kcal; plan 2,500 kcal → <b>−290 kcal/day</b> (deficit).`],
   ['How to read it',`Bulk: moderate surplus (about +200/+400); cut: deficit (about −300/−500); maintenance: close to zero.`],
   ['Limitations',`The requirement is an estimate (typical error ±10%); PAL is approximate. The real balance is verified with the weight trend (Analysis tab).`]],
  b:['FAO/WHO/UNU (2004). <i>Human energy requirements</i>. FAO Food and Nutrition Technical Report Series 1. Rome: FAO.',
     'Mifflin MD et al. (1990). A new predictive equation for resting energy expenditure in healthy individuals. <i>Am J Clin Nutr</i> 51(2):241–247.']},

'macro':{t:'Energy breakdown across macronutrients',
  dove:'Nutrition (side panel)',
  a:`Shows what share of the plan’s calories comes from protein, carbohydrates and fats, with the total grams and the grams per kg of body weight.`,
  s:[['What it shows',`A bar divided into three colors and, for each macronutrient, grams, percentage of energy and g/kg; at the bottom, fiber.`],
   ['Input data',`Grams of protein, available carbohydrates and fats of the plan’s foods; weight from the profile.`],
   ['Method and formulas',`Atwater factors:
     <div class="spf">E<sub>P</sub> = 4 × g<sub>P</sub> · E<sub>C</sub> = 4 × g<sub>C</sub> · E<sub>F</sub> = 9 × g<sub>F</sub><span class="spn">(1)</span></div>
     <div class="spf">Share<sub>x</sub> = <span class="fr"><i>E<sub>x</sub></i><i>E<sub>P</sub> + E<sub>C</sub> + E<sub>F</sub></i></span> × 100 · g/kg = <span class="fr"><i>g<sub>x</sub></i><i>weight</i></span><span class="spn">(2)</span></div>`],
   ['Worked example',`160 g of protein, 280 g of carbohydrates, 70 g of fat: 640 + 1,120 + 630 = 2,390 kcal → protein 27%, carbohydrates 47%, fat 26%; at 80 kg protein is 2.0 g/kg.`],
   ['How to read it',`For those who train with weights, protein is indicated between about 1.6 and 2.2 g/kg; the split between carbohydrates and fats depends on taste and training volume.`],
   ['Limitations',`The 4/4/9 sum may differ slightly from the database kcal (alcohol, polyols, rounding).`]],
  b:['Atwater WO, Bryant AP (1900). The availability and fuel value of food materials. <i>Storrs Agricultural Experiment Station Annual Report</i> 12:73–110.',
     'Morton RW et al. (2018). A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength. <i>Br J Sports Med</i> 52(6):376–384.']},

'energia-pasti':{t:'Energy per meal',
  dove:'Nutrition (side panel)',
  a:`Splits the plan’s calories across the meals of the day.`,
  s:[['What it shows',`One row per meal with a bar (the richest meal is the full bar), kcal and percentage of the total; at the bottom how many foods and recipes make up the plan.`],
   ['Input data',`Meal, food and grams of each row of the active-phase plan.`],
   ['Method and formulas',`<div class="spf">Share<sub>meal</sub> = <span class="fr"><i>Σ kcal of the meal’s foods</i><i>total kcal of the plan</i></span> × 100<span class="spn">(1)</span></div>`],
   ['Worked example',`Breakfast 500, lunch 800, snack 300, dinner 900 kcal out of 2,500: 20%, 32%, 12%, 36%.`],
   ['How to read it',`Useful for distributing energy and protein around training and for avoiding a meal that concentrates half of the day.`],
   ['Limitations',`It says nothing about the composition of the single meal: for that there is the table.`]],
  b:['Aragon AA, Schoenfeld BJ (2013). Nutrient timing revisited: is there a post-exercise anabolic window? <i>J Int Soc Sports Nutr</i> 10:5.']},

'nutrienti':{t:'Nutrients outside the WHO/FAO references',
  dove:'Nutrition (side panel)',
  a:`Lists the nutrients of the daily plan that fall short of the reference (targets) or exceed it (limits), according to the WHO/FAO recommendations for adults.`,
  s:[['What it shows',`Up to 8 nutrients with the percentage of the reference: red for exceeded limits and for targets below 60%, yellow for targets between 60% and 90%.`],
   ['Input data',`Nutrients of the plan’s foods; energy requirement and weight from the profile.`],
   ['Method and formulas',`<div class="spf">Index = <span class="fr"><i>daily amount in the plan</i><i>reference</i></span> × 100<span class="spn">(1)</span></div>
     References (E = requirement, or 2,000 kcal if missing): energy E; protein 0.83 g/kg; carbohydrates 55% E; fiber 25 g (targets, met from 90%); total fat ≤ 30% E; saturated ≤ 10% E; sugars ≤ 10% E; cholesterol ≤ 300 mg; sodium ≤ 2,000 mg (limits, met up to 100%); vitamins and minerals according to FAO/WHO values.`],
   ['Worked example',`Fiber 18 g out of 25 → <b>72%</b> (yellow, below target); sodium 2,600 mg out of 2,000 → <b>130%</b> (red, limit exceeded).`],
   ['How to read it',`These are population references for health, not sports targets: protein at 0.83 g/kg is the minimum for a sedentary adult. The 💡 next to a low nutrient lists the foods richest in it, per 100 g or per 100 kcal.`],
   ['Limitations',`Indicative references, not medical or nutritional advice; the quality of the values depends on the food database.`]],
  b:['WHO/FAO (2003). <i>Diet, nutrition and the prevention of chronic diseases</i>. WHO Technical Report Series 916. Geneva: WHO.',
     'WHO/FAO/UNU (2007). <i>Protein and amino acid requirements in human nutrition</i>. WHO Technical Report Series 935.',
     'World Health Organization (2015). <i>Guideline: sugars intake for adults and children</i>. Geneva: WHO.',
     'World Health Organization (2012). <i>Guideline: sodium intake for adults and children</i>. Geneva: WHO.']},

'timeline':{t:'Timeline: nutrition periods, load and weight',
  dove:'Analysis',
  a:`Puts on the same time axis the recorded nutrition phases (bulk, maintenance, cut), the Training Load and body weight, week by week.`,
  s:[['What it shows',`Colored bands for the phases (with the plan’s daily kcal), the TL line (left axis) and the weight line (right axis).`],
   ['Input data',`Nutrition periods (Nutrition → Periods: phase, dates, plan); weekly TL from History; weight from the measurement history.`],
   ['Method and formulas',`The weeks are the union of those with TL, weight or a period. Each axis is scaled between the minimum and maximum of the values, with a 10% margin:
     <div class="spf">y = top + height × (1 − <span class="fr"><i>v − (min − 0.1·Δ)</i><i>1.2·Δ</i></span>), &nbsp; Δ = max − min<span class="spn">(1)</span></div>
     If two periods overlap the last one recorded applies.`],
   ['Worked example',`8 weeks of bulk at 3,000 kcal (green band) with TL from 25,000 to 30,000 and weight from 78 to 80 kg, then 6 weeks of cut at 2,300 kcal with falling weight.`],
   ['How to read it',`It serves to see causes and effects together: how load and weight change on entering a phase.`],
   ['Limitations',`The two axes have different scales: the crossing of the lines has no meaning.`]],
  b:['Tufte ER (2001). <i>The Visual Display of Quantitative Information</i>, 2nd ed. Cheshire: Graphics Press.']},

'bilancio-peso':{t:'Weight change versus calorie balance',
  dove:'Analysis',
  a:`Checks on one’s own data how much the plan’s calorie balance translates into weight change the following week, with Pearson correlation and a regression line.`,
  s:[['What it shows',`One point per week: on the x-axis the balance (plan kcal − metabolism), on the y-axis the weight change in the following week; color by phase; regression line and r.`],
   ['Input data',`Daily kcal of the active period, metabolism and weight from the measurement history. Two consecutive weeks with complete data are needed; at least 3 points.`],
   ['Method and formulas',`<div class="spf">x<sub>t</sub> = kcal<sub>plan,t</sub> − metabolism<sub>t</sub> · y<sub>t</sub> = weight<sub>t+1</sub> − weight<sub>t</sub><span class="spn">(1)</span></div>
     <div class="spf">b = <span class="fr"><i>Σ (x − x̄)(y − ȳ)</i><i>Σ (x − x̄)²</i></span> · a = ȳ − b·x̄<span class="spn">(2)</span></div>
     <div class="spf">r = <span class="fr"><i>Σ (x − x̄)(y − ȳ)</i><i>√( Σ (x − x̄)² · Σ (y − ȳ)² )</i></span><span class="spn">(3)</span></div>
     Below the chart: “every 100 kcal/d of surplus ≈ 100·b kg/week”; if |r| &lt; 0.3 the correlation is flagged as weak.`],
   ['Worked example',`Five weeks with balance −400, −200, 0, +200, +400 kcal/d and Δweight −0.35, −0.20, +0.05, +0.15, +0.40 kg: b = 0.000925 → <b>0.09 kg/week per 100 kcal/d</b>; r = 0.99. It is consistent with the theoretical estimate: 700 kcal per week ≈ 0.09 kg of tissue.`],
   ['How to read it',`A slope close to the theoretical one confirms that metabolism and plan are well estimated; a flat slope or low r indicate estimates to be reviewed or little data.`],
   ['Limitations',`Weight varies a lot with water and glycogen; the relationship between balance and weight is not linear in the long run (metabolic adaptation). Correlation is not causation.`]],
  b:['Hall KD et al. (2011). Quantification of the effect of energy imbalance on bodyweight. <i>Lancet</i> 378(9793):826–837.',
     'Pearson K (1895). Notes on regression and inheritance in the case of two parents. <i>Proc R Soc Lond</i> 58:240–242.']},

'ritardo':{t:'Lagged correlation between load and weight',
  dove:'Analysis',
  a:`Measures with what delay the training load of one week is reflected in weight change: Pearson correlation between the TL of week N and Δweight from 1 to 5 weeks later.`,
  s:[['What it shows',`Five bars (+1 … +5 weeks) with the coefficient r: green if positive, red if negative. At the top, how many pairs enter the first computation.`],
   ['Input data',`Weekly TL and weight; weight differences only between consecutive weeks.`],
   ['Method and formulas',`<div class="spf">Δweight<sub>k</sub> = weight<sub>k+1</sub> − weight<sub>k</sub> · r<sub>L</sub> = Pearson( TL<sub>i</sub> , Δweight<sub>i+L</sub> ), L = 0…4<span class="spn">(1)</span></div>
     The “+1” bar corresponds to L = 0 (weight of the following week); at least 3 pairs are needed.`],
   ['Worked example',`r = 0.10 at +1, 0.35 at +2, 0.52 at +3, 0.30 at +4, 0.05 at +5: the load “shows up” on weight mainly after about three weeks.`],
   ['How to read it',`The peak indicates the typical delay; values all close to zero say that, in your data, load does not explain weight changes.`],
   ['Limitations',`With few weeks r is unstable; diet and load change together and are confounded; no correction for multiple comparisons.`]],
  b:['Box GEP, Jenkins GM, Reinsel GC (2008). <i>Time Series Analysis: Forecasting and Control</i>, 4th ed. Hoboken: Wiley.']},

'confronto-fasi':{t:'Comparison between nutrition phases (boxplot)',
  dove:'Analysis',
  a:`Compares the bulk, maintenance and cut phases for the weekly change in Training Load (in %) and in weight (in kg), with one boxplot per phase.`,
  s:[['What it shows',`For each phase with at least 3 weeks: box between first and third quartile, line at the median, whiskers to minimum and maximum; dashed line at zero.`],
   ['Input data',`Pairs of consecutive weeks within a phase, with TL (for the first chart) or weight (for the second).`],
   ['Method and formulas',`<div class="spf">ΔTL%<sub>t</sub> = ( <span class="fr"><i>TL<sub>t</sub></i><i>TL<sub>t−1</sub></i></span> − 1 ) × 100 · Δweight<sub>t</sub> = weight<sub>t</sub> − weight<sub>t−1</sub><span class="spn">(1)</span></div>
     Quantiles with linear interpolation on the sorted values v<sub>0</sub> … v<sub>n−1</sub>:
     <div class="spf">Q(p) = v<sub>⌊h⌋</sub> + (h − ⌊h⌋)(v<sub>⌈h⌉</sub> − v<sub>⌊h⌋</sub>), &nbsp; h = (n − 1)·p<span class="spn">(2)</span></div>`],
   ['Worked example',`ΔTL% in bulk: −2, 3, 5, 6, 10 → Q1 = 3, median = 5, Q3 = 6, minimum −2, maximum 10. Δweight in cut: −0.6, −0.4, −0.3, −0.3, −0.1 kg → median −0.3 kg per week.`],
   ['How to read it',`Boxes that do not overlap indicate truly different phases; a wide box indicates highly variable weeks.`],
   ['Limitations',`With few weeks per phase the quartiles are not very stable; the boxplot does not show the temporal sequence.`]],
  b:['Tukey JW (1977). <i>Exploratory Data Analysis</i>. Reading: Addison-Wesley.',
     'Hyndman RJ, Fan Y (1996). Sample quantiles in statistical packages. <i>The American Statistician</i> 50(4):361–365.']}
};
